//! Cairn desktop app: a thin Tauri layer over `cairn-core` (docs/development.md "Layout", spec TC-13..15).
//!
//! Adding a command: write it in `commands/<area>.rs` with `#[tauri::command]` and
//! `#[specta::specta]`, then list it in `specta_builder()`. The TypeScript bindings
//! (`app/src/api/bindings.ts`) are regenerated by `cargo test -p cairn` or by starting a debug build.

mod backups;
mod commands;
mod error;
mod events;
mod indexer;
mod knowledge_folder;
pub mod llm;
mod logging;
pub mod search_model;
pub mod selftest;
pub mod sidecar;
mod state;
#[cfg(windows)]
mod winjob;

