pub fn export_bindings(builder: &tauri_specta::Builder<tauri::Wry>) {
    builder
        .export(
            specta_typescript::Typescript::default().header("// Generated from the Rust code by tauri-specta (spec TC-14). Do not edit.\n// @ts-nocheck"),
            BINDINGS_PATH,
        )
        .expect("failed to export TypeScript bindings");
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let paths = cairn_core::DataPaths::new(cairn_core::paths::resolve_data_dir());
    let logs = logging::init(&paths.logs_dir());
    let builder = specta_builder();
    #[cfg(debug_assertions)]
    export_bindings(&builder);

    // D-56: on Windows, WebView2's own storage lives in `<data folder>\webview`, so the app folder
    // holds everything except the keys. Tauri forces the webview's data folder to the "app local
    // data" folder (ignoring WEBVIEW2_USER_DATA_FOLDER), and that folder can be overridden in the
    // context before the app is built, which is the supported way and needs no `unsafe`.
    #[allow(unused_mut)]
    let mut context = tauri::generate_context!();
    #[cfg(windows)]
    {
        use tauri::utils::config::{AppDirectoriesOverride, AppDirectoryOverrides};
        context.config_mut().app.app_directories_override =
            Some(AppDirectoriesOverride::Directories(AppDirectoryOverrides {
                local_data: Some(paths.webview_dir()),
                ..Default::default()
            }));
    }

    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        .plugin(navigation_guard())
        .on_page_load(|webview, payload| {
            // `CAIRN_DEV_SCRIPT_AFTER=load`: the script starts as soon as the page has loaded.
            if webview.label() == "main"
                && matches!(payload.event(), tauri::webview::PageLoadEvent::Finished)
                && dev_script_after_load()
                && !SCRIPT_STARTED.swap(true, std::sync::atomic::Ordering::SeqCst)
                && let Some(script) = dev_script_source()
            {
                tracing::info!("running CAIRN_DEV_SCRIPT_FILE (page loaded)");
                if let Err(e) = webview.eval(&script) {
                    tracing::warn!(error = %e, "CAIRN_DEV_SCRIPT_FILE failed");
                }
            }
        })
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            app.manage(logs);
            // Pasted images are shown through the asset protocol, only from the attachments folder
            // (and, in external mode, the knowledge folder: `knowledge_folder`).
            let _ = app
                .asset_protocol_scope()
                .allow_directory(paths.attachments_dir(), false);
            // NFR-SEC-1: development builds keep their keys apart from an installed copy.
            let service = if cfg!(debug_assertions) {
                "cairn-dev"
            } else {
                "cairn"
            };
            // Development builds: CAIRN_DEV_MEMORY_KEYS=1 keeps API keys in memory for this run, so a
            // scripted check can use a provider that needs a key without touching the system keychain.
            let memory_keys = cfg!(debug_assertions)
                && std::env::var("CAIRN_DEV_MEMORY_KEYS").is_ok_and(|v| v == "1");
            let secrets: Arc<dyn cairn_core::secrets::SecretStore> = if memory_keys {
                tracing::info!("API keys are kept in memory for this run (CAIRN_DEV_MEMORY_KEYS)");
                Arc::new(cairn_core::secrets::MemoryStore::default())
            } else {
                Arc::new(cairn_core::secrets::OsKeychain::new(service))
            };
            let model_paths = paths.clone();
            let app_state = state::AppState::open(paths, secrets);
            // D-72: `folder:` images of the external knowledge folder are shown the same way.
            if let Some(root) = app_state.knowledge_root() {
                let _ = app.asset_protocol_scope().allow_directory(root, true);
            }
            // TC-12: the two AI worker processes start on demand; the idle timeout comes from settings.
            let idle_min = app_state.idle_timeout_min();
            let status_app = app.handle().clone();
            app.manage(sidecar::Sidecars::new(
                sidecar::SidecarConfig::resolve(idle_min, app.path().resource_dir().ok())
                    .with_added_model(&model_paths),
                Arc::new(move |status| {
                    // The UI shows the workers' state (Settings › Search); a failed emit only gets logged.
                    if let Err(e) = status.emit(&status_app) {
                        tracing::warn!(error = %e, "failed to emit SidecarStatus");
                    }
                }),
            ));
            app.manage(app_state);
            // M5: running LLM work that *Stop* can end, and uploads in progress.
            app.manage(Arc::new(llm::Jobs::default()));
            app.manage(commands::files::Uploads::default());
            app.manage(indexer::Indexer::start(app.handle().clone()));
            // D-82: a search model added later, and a download to resume.
            app.manage(search_model::SearchModel::start(app.handle().clone(), model_paths));
            // D-72: in external mode, the start-up scan and the folder watcher.
            app.manage(knowledge_folder::KnowledgeFolder::start(app.handle().clone()));
            // NFR-REL-2: the daily backup.
            backups::start(app.handle().clone());
            exit_after_env(app.handle().clone());
            dev_script_env(app.handle().clone());
            Ok(())
        })
        .run(context)
        .expect("error while running Cairn");
}

/// The window only ever shows the app's own pages. WebKit opens a file dropped where nothing takes
/// it as the page itself, which also loses the UI's close handling (the window then can't be
/// closed); a link could do the same. The UI cancels such drops (`app/src/lib/dropGuard.ts`); this
/// blocks whatever gets past it. In-app routing (history API) is not a navigation.
fn navigation_guard() -> tauri::plugin::TauriPlugin<tauri::Wry> {
    tauri::plugin::Builder::new("navigation-guard")
        .on_navigation(|_webview, url| {
            let host = url.host_str().unwrap_or("");
            let ours = match url.scheme() {
                "tauri" => true,
                "http" | "https" => {
                    host == "tauri.localhost"
                        || (cfg!(debug_assertions) && matches!(host, "localhost" | "127.0.0.1"))
                }
                _ => url.as_str() == "about:blank",
            };
            if !ours {
                // The scheme only: a file path or link may be private.
                tracing::warn!(scheme = url.scheme(), "blocked a navigation away from the app");
            }
            ours
        })
        .build()
}

/// Scripted runs (docs/development.md, "Automation"): always allowed in debug builds; a release build
/// needs `CAIRN_AUTOMATION=1` as well, so an installed copy never reacts to a stray variable
/// (NFR-PERF-6: `make measure` runs the AppImage this way).
fn automation_allowed() -> bool {
    cfg!(debug_assertions) || automation_on()
}

/// `CAIRN_AUTOMATION=1`.
fn automation_on() -> bool {
    std::env::var("CAIRN_AUTOMATION").is_ok_and(|v| v == "1")
}

/// `CAIRN_EXIT_AFTER_SECS=N` closes the main window after N seconds the same way the window's
/// close button does (so the UI's close handling is exercised), and forces an exit if the window
/// is still open 5 s later. Scripted test runs end by themselves instead of being killed.
/// Debug builds, or release builds with `CAIRN_AUTOMATION=1`.
fn exit_after_env(app: tauri::AppHandle) {
    if !automation_allowed() {
        return;
    }
    if let Some(secs) = std::env::var("CAIRN_EXIT_AFTER_SECS")
        .ok()
        .and_then(|s| s.parse::<u64>().ok())
    {
        std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_secs(secs));
            tracing::info!("CAIRN_EXIT_AFTER_SECS reached, closing the main window");
            if let Some(window) = app.get_webview_window("main") {
                let _ = window.close();
            }
            std::thread::sleep(std::time::Duration::from_secs(5));
            tracing::warn!("the main window did not close within 5 s; forcing exit");
            app.exit(0);
        });
    }
}

/// Set once the script has been started from the page-load event.
static SCRIPT_STARTED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// `CAIRN_DEV_SCRIPT_AFTER=load`: start the script when the page has loaded, not after a delay.
/// Start-up measuring needs this, because the script has to be there before the UI renders.
fn dev_script_after_load() -> bool {
    automation_allowed()
        && std::env::var_os("CAIRN_DEV_SCRIPT_FILE").is_some()
        && std::env::var("CAIRN_DEV_SCRIPT_AFTER").is_ok_and(|v| v == "load")
}

fn dev_script_source() -> Option<String> {
    let path = std::env::var_os("CAIRN_DEV_SCRIPT_FILE")?;
    match std::fs::read_to_string(&path) {
        Ok(s) => Some(s),
        Err(e) => {
            tracing::warn!(error = %e, "CAIRN_DEV_SCRIPT_FILE could not be read");
            None
        }
    }
}

/// `CAIRN_DEV_SCRIPT_FILE=<path.js>` runs that JavaScript in the main window
/// `CAIRN_DEV_SCRIPT_AFTER` seconds (default 6) after start, or when the page has loaded if that
/// is `load`. For scripted checks of UI behaviour without clicking or typing in the window
/// (docs/development.md, "Checking the app without clicking"). Debug builds, or release builds with
/// `CAIRN_AUTOMATION=1`. A script can report back with `fetch` to a local listener in a debug
/// build, and with the `automation_report` command in any build.
fn dev_script_env(app: tauri::AppHandle) {
    if !automation_allowed() || dev_script_after_load() {
        return;
    }
    let Some(path) = std::env::var_os("CAIRN_DEV_SCRIPT_FILE") else {
        return;
    };
    let after = std::env::var("CAIRN_DEV_SCRIPT_AFTER")
        .ok()
        .and_then(|s| s.parse::<u64>().ok())
        .unwrap_or(6);
    std::thread::spawn(move || {
        let script = match std::fs::read_to_string(&path) {
            Ok(s) => s,
            Err(e) => {
                tracing::warn!(error = %e, "CAIRN_DEV_SCRIPT_FILE could not be read");
                return;
            }
        };
        std::thread::sleep(std::time::Duration::from_secs(after));
        if let Some(window) = app.get_webview_window("main") {
            tracing::info!("running CAIRN_DEV_SCRIPT_FILE");
            if let Err(e) = window.eval(&script) {
                tracing::warn!(error = %e, "CAIRN_DEV_SCRIPT_FILE failed");
            }
        }
    });
}

/// Appends one line to the file named by `CAIRN_AUTOMATION_OUT`, so a script running in the window
/// can report back when the content security policy allows no connections but Tauri's own (a
/// `fetch` to a local listener fails in a release build). Only works with `CAIRN_AUTOMATION=1`.
#[tauri::command]
#[specta::specta]
async fn automation_report(line: String) -> Result<(), ApiError> {
    use std::io::Write;
    let refuse = |message: &str| ApiError {
        kind: "invalid".into(),
        message: message.into(),
    };
    if !automation_on() {
        return Err(refuse("Automation is off (CAIRN_AUTOMATION=1 is not set)."));
    }
    let Some(path) = std::env::var_os("CAIRN_AUTOMATION_OUT") else {
        return Err(refuse("CAIRN_AUTOMATION_OUT is not set."));
    };
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|e| ApiError::internal(e.to_string()))?;
    // One write call, so lines from overlapping reports never mix.
    let mut text = line.replace('\n', " ");
    text.push('\n');
    file.write_all(text.as_bytes())
        .map_err(|e| ApiError::internal(e.to_string()))
}

#[cfg(test)]
mod tests {
    /// `cargo test -p cairn` keeps `app/src/api/bindings.ts` in step with the Rust code.
    #[test]
    fn export_typescript_bindings() {
        super::export_bindings(&super::specta_builder());
    }

    /// The report command writes only when automation is switched on (M7, NFR-PERF-6).
    #[test]
    fn automation_report_needs_the_switch() {
        if super::automation_on() {
            return; // run by `make measure`-style env: nothing to check here
        }
        let err = tauri::async_runtime::block_on(super::automation_report("x".into()));
        assert!(err.is_err());
    }
}
